invoice:
declare v_invoice_id text; v_attempt_id uuid; v_match_count integer; v_order public.orders; v_new_status text;
begin if p_stripe_invoice_id is null or btrim(p_stripe_invoice_id) = '' or p_refunded_total_cents is null or p_refunded_total_cents < 0 then return 'invalid_input'; end if;
v_invoice_id := btrim(p_stripe_invoice_id);
select count(*) into v_match_count from public.checkout_attempts where stripe_invoice_id = v_invoice_id;
if v_match_count = 0 then return 'order_not_found'; end if;
if v_match_count > 1 then return 'ambiguous_invoice_correlation'; end if;
select id into v_attempt_id from public.checkout_attempts where stripe_invoice_id = v_invoice_id;
if not found then return 'order_not_found'; end if;
select count(*) into v_match_count from public.orders where checkout_attempt_id = v_attempt_id;
if v_match_count = 0 then return 'order_missing_for_attempt'; end if;
if v_match_count > 1 then return 'ambiguous_invoice_correlation'; end if;
select * into v_order from public.orders where checkout_attempt_id = v_attempt_id for update;
if not found then return 'order_missing_for_attempt'; end if;
if v_order.payment_status not in ('paid','refund_pending','partially_refunded','refunded') then return 'not_applicable'; end if;
if p_refunded_total_cents > v_order.total_gross_cents then return 'invalid_amount'; end if;
if p_refunded_total_cents >= v_order.total_gross_cents and v_order.total_gross_cents > 0 then v_new_status := 'refunded'; elsif p_refunded_total_cents > 0 then v_new_status := 'partially_refunded'; elsif coalesce(p_has_pending_refund,false) then v_new_status := 'refund_pending'; else v_new_status := 'paid'; end if;
if v_order.payment_status = v_new_status and v_order.refunded_total_cents is not distinct from p_refunded_total_cents then return 'unchanged'; end if;
update public.orders set payment_status=v_new_status,refunded_total_cents=p_refunded_total_cents,refund_updated_at=now() where id=v_order.id;
return 'applied'; end;

once:
declare v_order public.orders; v_match_count integer; v_new_status text;
begin if p_payment_intent_id is null or btrim(p_payment_intent_id) = '' or p_refunded_total_cents is null or p_refunded_total_cents < 0 then return 'invalid_input'; end if;
lock table public.orders in exclusive mode;
select count(*) into v_match_count from public.orders where stripe_payment_intent_id = p_payment_intent_id;
if v_match_count = 0 then return 'order_not_found'; end if;
if v_match_count > 1 then return 'ambiguous_payment_intent'; end if;
select * into v_order from public.orders where stripe_payment_intent_id = p_payment_intent_id for update;
if not found then return 'order_not_found'; end if;
if v_order.payment_status not in ('paid','refund_pending','partially_refunded','refunded') then return 'not_applicable'; end if;
if p_refunded_total_cents > v_order.total_gross_cents then return 'invalid_amount'; end if;
if p_refunded_total_cents >= v_order.total_gross_cents and v_order.total_gross_cents > 0 then v_new_status := 'refunded'; elsif p_refunded_total_cents > 0 then v_new_status := 'partially_refunded'; elsif coalesce(p_has_pending_refund,false) then v_new_status := 'refund_pending'; else v_new_status := 'paid'; end if;
if v_order.payment_status = v_new_status and v_order.refunded_total_cents is not distinct from p_refunded_total_cents then return 'unchanged'; end if;
